<?php
require_once '../config/db.php';if(session_status()===PHP_SESSION_NONE)session_start();if(!isset($_SESSION['user_id']))redirect('../index.php');$error='';
try{if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();
 if(isset($_POST['add_category'])){$name=trim((string)$_POST['category_name']);if($name==='')throw new RuntimeException('Category name is required.');$pdo->prepare('INSERT INTO expense_categories(name) VALUES(?)')->execute([$name]);redirect('expenses.php?saved=category');}
 if(isset($_POST['save_expense'])){$account=(int)$_POST['account_id'];$category=(int)$_POST['category_id'];$amount=round((float)$_POST['amount'],2);$code=$_POST['currency_code'];if($amount<=0)throw new RuntimeException('Amount must be greater than zero.');$s=$pdo->prepare('SELECT name FROM expense_categories WHERE id=? AND is_active=1');$s->execute([$category]);$categoryName=$s->fetchColumn();$s=$pdo->prepare('SELECT exchange_rate FROM currencies WHERE code=?');$s->execute([$code]);$rate=(float)$s->fetchColumn();if(!$categoryName||$rate<=0)throw new RuntimeException('Choose a valid category and currency.');$baseAmount=round($amount/$rate,2);$pdo->beginTransaction();$pdo->prepare('INSERT INTO expenses(account_id,category_id,category,amount,currency_code,exchange_rate,base_amount,expense_date,reference_note) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$account,$category,$categoryName,$amount,$code,$rate,$baseAmount,$_POST['expense_date'],trim((string)$_POST['reference_note'])]);$pdo->prepare('UPDATE accounts SET current_balance=current_balance-? WHERE id=?')->execute([$baseAmount,$account]);$pdo->commit();redirect('expenses.php?saved=expense');}
 }}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof PDOException&&$e->getCode()==='23000'?'That category already exists.':$e->getMessage();}
$accounts=$pdo->query('SELECT id,account_name,current_balance FROM accounts WHERE is_active=1 ORDER BY account_name')->fetchAll();$categories=$pdo->query('SELECT * FROM expense_categories WHERE is_active=1 ORDER BY name')->fetchAll();$currencies=$pdo->query('SELECT code,name,symbol,exchange_rate FROM currencies ORDER BY is_base_currency DESC,name')->fetchAll();$start=$_GET['start']??date('Y-m-01');$end=$_GET['end']??date('Y-m-d');$categoryFilter=(int)($_GET['category']??0);$currencyFilter=$_GET['currency']??'';$accountFilter=(int)($_GET['account']??0);$where=['e.expense_date BETWEEN ? AND ?'];$params=[$start,$end];if($categoryFilter){$where[]='e.category_id=?';$params[]=$categoryFilter;}if(preg_match('/^[A-Z]{3}$/',$currencyFilter)){$where[]='e.currency_code=?';$params[]=$currencyFilter;}if($accountFilter){$where[]='e.account_id=?';$params[]=$accountFilter;}$s=$pdo->prepare('SELECT e.*,a.account_name,c.symbol FROM expenses e JOIN accounts a ON a.id=e.account_id JOIN currencies c ON c.code=e.currency_code WHERE '.implode(' AND ',$where).' ORDER BY e.expense_date DESC,e.id DESC');$s->execute($params);$expenses=$s->fetchAll();$baseTotal=array_sum(array_column($expenses,'base_amount'));require_once 'includes/header.php';require_once 'includes/sidebar.php';$input='mt-1 w-full border rounded-lg px-3 py-2.5';
?>
<main class="flex-1 h-screen overflow-y-auto app-scroll"><header class="bg-white border-b px-5 md:px-8 py-5 flex items-center gap-4 sticky top-0 z-10"><button data-sidebar-toggle class="lg:hidden text-2xl">☰</button><div><h2 class="text-2xl font-bold">Expenses</h2><p class="text-sm text-slate-500">Categories, currencies, and flexible list filters</p></div></header><div class="p-5 md:p-8 max-w-7xl mx-auto"><?php if($error):?><div class="bg-rose-50 border p-4 rounded-xl mb-5"><?=h($error)?></div><?php endif;?><?php if(isset($_GET['saved'])):?><div class="bg-emerald-50 border p-4 rounded-xl mb-5">Changes saved.</div><?php endif;?><div class="grid xl:grid-cols-3 gap-7"><div class="space-y-6"><form method="post" class="bg-white border rounded-2xl p-6 space-y-4"><?=csrf_field()?><h3 class="font-bold text-lg">Record expense</h3><label class="block text-sm">Payment account<select name="account_id" class="<?=$input?> bg-white"><?php foreach($accounts as $a):?><option value="<?=$a['id']?>"><?=h($a['account_name'])?> · <?=money($pdo,$a['current_balance'])?></option><?php endforeach;?></select></label><label class="block text-sm">Category<select name="category_id" class="<?=$input?> bg-white"><?php foreach($categories as $c):?><option value="<?=$c['id']?>"><?=h($c['name'])?></option><?php endforeach;?></select></label><div class="grid grid-cols-2 gap-3"><label class="text-sm">Amount<input type="number" name="amount" min="0.01" step="0.01" required class="<?=$input?>"></label><label class="text-sm">Currency<select name="currency_code" class="<?=$input?> bg-white"><?php foreach($currencies as $c):?><option value="<?=$c['code']?>"><?=h($c['code'].' '.$c['symbol'])?></option><?php endforeach;?></select></label></div><label class="block text-sm">Date<input type="date" name="expense_date" value="<?=date('Y-m-d')?>" required class="<?=$input?>"></label><label class="block text-sm">Reference / note<textarea name="reference_note" rows="2" class="<?=$input?>"></textarea></label><button name="save_expense" class="brand-bg text-white rounded-lg px-5 py-2.5 w-full font-semibold">Save expense</button></form><form method="post" class="bg-white border rounded-2xl p-6"><?=csrf_field()?><h3 class="font-bold">Create expense category</h3><div class="flex gap-2 mt-3"><input name="category_name" required placeholder="New category" class="border rounded-lg px-3 py-2 flex-1"><button name="add_category" class="bg-slate-900 text-white rounded-lg px-4">Add</button></div><div class="flex flex-wrap gap-2 mt-4"><?php foreach($categories as $c):?><span class="bg-slate-100 rounded-full px-3 py-1 text-xs font-semibold"><?=h($c['name'])?></span><?php endforeach;?></div></form></div>
<section class="xl:col-span-2 bg-white border rounded-2xl overflow-hidden h-fit"><div class="p-5 border-b flex justify-between"><div><h3 class="font-bold text-lg">Expense list</h3><p class="text-sm text-slate-500"><?=count($expenses)?> records in selected period</p></div><strong class="text-xl text-rose-700"><?=money($pdo,$baseTotal)?></strong></div><form class="p-4 bg-slate-50 grid sm:grid-cols-2 lg:grid-cols-5 gap-2"><input type="date" name="start" value="<?=h($start)?>" class="border rounded px-2 py-2"><input type="date" name="end" value="<?=h($end)?>" class="border rounded px-2 py-2"><select name="category" class="border rounded px-2 bg-white"><option value="">All categories</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=$categoryFilter===$c['id']?'selected':''?>><?=h($c['name'])?></option><?php endforeach;?></select><select name="currency" class="border rounded px-2 bg-white"><option value="">All currencies</option><?php foreach($currencies as $c):?><option value="<?=$c['code']?>" <?=$currencyFilter===$c['code']?'selected':''?>><?=$c['code']?></option><?php endforeach;?></select><button class="bg-slate-900 text-white rounded px-3">Filter</button><select name="account" class="border rounded px-2 py-2 bg-white lg:col-span-2"><option value="">All accounts</option><?php foreach($accounts as $a):?><option value="<?=$a['id']?>" <?=$accountFilter===$a['id']?'selected':''?>><?=h($a['account_name'])?></option><?php endforeach;?></select></form><div class="overflow-x-auto"><table class="w-full text-sm"><thead><tr class="bg-slate-50"><th class="text-left p-4">Date</th><th class="text-left p-4">Category</th><th class="text-left p-4">Account</th><th class="text-right p-4">Original amount</th><th class="text-right p-4">Base amount</th></tr></thead><tbody class="divide-y"><?php foreach($expenses as $e):?><tr><td class="p-4"><?=h(date('M j, Y',strtotime($e['expense_date'])))?><p class="text-xs text-slate-400"><?=h($e['reference_note'])?></p></td><td class="p-4 font-semibold"><?=h($e['category'])?></td><td class="p-4"><?=h($e['account_name'])?></td><td class="p-4 text-right font-semibold"><?=h($e['symbol']).number_format($e['amount'],2)?> <span class="text-xs text-slate-400"><?=h($e['currency_code'])?></span></td><td class="p-4 text-right"><?=money($pdo,$e['base_amount'])?></td></tr><?php endforeach;?><?php if(!$expenses):?><tr><td colspan="5" class="p-10 text-center text-slate-500">No expenses match these filters.</td></tr><?php endif;?></tbody></table></div></section></div></div></main><?php require_once 'includes/footer.php';?>
